**Server-side (Node.js with Express):**

```javascript
const express = require('express');
const app = express();
const port = 3000;

// In-memory storage for CSRF tokens (for simplicity, use a database in a real application)
const csrfTokens = {};

app.get('/generate-csrf-token', (req, res) => {
  // Generate a unique token (you can improve this with a more robust method)
  const csrfToken = `CSRF_${Date.now()}${Math.random().toString(36).substring(7)}`;

  csrfTokens[req.ip] = csrfToken; // Store the token associated with the client IP

  res.json({ csrfToken });
});

app.post('/account/transferFunds', (req, res) => {
  const csrfToken = req.body.csrfToken;

  // Verify the CSRF token here by checking if it exists in your storage and matches the request origin
  if (csrfTokens[req.ip] === csrfToken) {
    // Process the transfer funds request
    console.log('Processing funds transfer:', req.body);
    res.status(200).send('Transfer processed');
  } else {
    res.status(403).send('Forbidden: Invalid CSRF token');
  }
});

app.listen(port, () => {
  console.log(`Server running at http://localhost:${port}`);
});
```

